mapper.sql:
with assetHold as (select gavInfo.publisher,gavInfo.finprodAbbr,gavInfo.finprodMarketId,gavInfo.portFolioName, gavInfo.marketValue,gavInfo.dscCostAmt,gavInfo.shareAmt, round(nvl(gavInfo.marketValue,0)/ppvInfo.tdyAssetValue*100,2) as marketValueRatio,gavInfo.portfolioId,ppvInfo.tdyAssetValue from (select mci.customer_name publisher,psv.CDATE cdate,psv.PORTFOLIO_ID portfolioId,psv.FINPROD_ID finprodId,psv.SHARE_AMT shareAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*psv.DSC_COST_AMT when fpt.TYPE_6 = 'L02' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT else psv.DSC_COST_AMT end as dscCostAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) when fpt.TYPE_6 = 'L02' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) else (NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) end as marketValue, pp.PORTFOLIO_NAME portFolioName,fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr from PTL_SEC_VALUTION psv inner join PTL_PORTFOLIO pp on psv.PORTFOLIO_ID=pp.PORTFOLIO_ID inner join FIN_PRODUCT fp on fp.FINPROD_ID=psv.FINPROD_ID inner join MST_CUSTOMER_INFO mci on (fp.ISSUER = mci.CUSTOMER_ID or (fp.MANAGER = mci.CUSTOMER_ID and fp.finprod_type2 = 'F06') or (fp.FINANCIER = mci.CUSTOMER_ID and fp.finprod_type2 = 'F18')) inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID where 1=1
AND mci.CUSTOMER_ID IN
#{item}
and to_char(psv.CDATE,'yyyy-mm-dd') = #{searchDate}
)gavInfo left join (select ppv.CDATE cdate,ppv.PORTFOLIO_ID portfolioId,nvl(ppv.TDY_ASSET_VALUE,0) tdyAssetValue from PTL_PORTFOLIO_VALUATION ppv where 1=1
and to_char(ppv.CDATE,'yyyy-mm-dd')= #{searchDate}
)ppvInfo on ppvInfo.portfolioId=gavInfo.portfolioId and ppvInfo.cdate=gavInfo.cdate where ppvInfo.tdyAssetValue !=0 )

select.if:
select assetHold1.publisher, null finprodAbbr, null portFolioName, sum(assetHold1.marketValue) as marketValue, sum(assetHold1.dscCostAmt) as dscCostAmt, sum(assetHold1.shareAmt) as shareAmt, null marketValueRatio, /**round(sum(nvl(assetHold.marketValue,0))/sum(assetHold.tdyAssetValue)*100,2) as marketValueRatio,*/ null portfolioId,'02' as hasChildren ,'root' parentInfo,assetHold1.publisher childInfo /*,assetHold1.belongInstitutionCode*/ from ( SELECT assetHold.*, DATAINST.BELONG_INSTITUTION_CODE belongInstitutionCode FROM assetHold LEFT JOIN DATA_AUTH_NOTIFY_INST DATAINST ON assetHold.portfolioId = DATAINST.BUSINESS_ID AND DATAINST.DATA_TYPE='PTL01' AND DATAINST.MODEL_TYPE = '02' WHERE 1=1
AND DATAINST.INSTITUTION_CODE IN
#{item}
) assetHold1 group by assetHold1.publisher/*,assetHold1.belongInstitutionCode*//**,finprodMarketId,finprodAbbr*/

SELECT NULL publisher, assetHold1.finprodMarketId, assetHold1.finprodAbbr finprodAbbr, null portFolioName, sum(assetHold1.marketValue) marketValue, sum(assetHold1.dscCostAmt) dscCostAmt, sum(assetHold1.shareAmt) shareAmt, null marketValueRatio, null portfolioId, '01' AS hasChildren, assetHold1.publisher parentInfo, assetHold1.publisher||assetHold1.finprodMarketId childInfo ,null belongInstitutionCodeNew FROM ( SELECT assetHold.*, DATAINST.BELONG_INSTITUTION_CODE belongInstitutionCode FROM assetHold LEFT JOIN DATA_AUTH_NOTIFY_INST DATAINST ON assetHold.portfolioId = DATAINST.BUSINESS_ID AND DATAINST.DATA_TYPE='PTL01' AND DATAINST.MODEL_TYPE = '02' WHERE 1=1
AND DATAINST.INSTITUTION_CODE IN
#{item}
) assetHold1 group by assetHold1.publisher,assetHold1.finprodMarketId,assetHold1.finprodAbbr union all SELECT NULL publisher, NULL finprodMarketId, NULL finprodAbbr, assetHold1.portFolioName, assetHold1.marketValue, assetHold1.dscCostAmt, assetHold1.shareAmt, assetHold1.marketValueRatio, assetHold1.portfolioId, '01' AS hasChildren, assetHold1.publisher||assetHold1.finprodMarketId parentInfo, assetHold1.portFolioName childInfo ,assetHold1.belongInstitutionCode belongInstitutionCodeNew FROM ( SELECT assetHold.*, DATAINST.BELONG_INSTITUTION_CODE belongInstitutionCode FROM assetHold LEFT JOIN DATA_AUTH_NOTIFY_INST DATAINST ON assetHold.portfolioId = DATAINST.BUSINESS_ID AND DATAINST.DATA_TYPE='PTL01' AND DATAINST.MODEL_TYPE = '02' WHERE 1=1
AND DATAINST.INSTITUTION_CODE IN
#{item}
) assetHold1
